// DownloadFolder Returns a folder as a tar archive (`application/x-tar`, or `application/gzip` with gzip), packed by tar in the function as it streams, of any size; its entries are relative to the folder (`./a.txt`). A folder that fails part way (a file it may not read, or one that changes as it is read) ends as an archive every tar reader refuses, never as a short one that reads whole. At most 4 at once in a function. A paused function is woken first.
func (g *FunctionMachineFiles) DownloadFolder(ctx context.Context, path string, q *FunctionDownloadFolderQuery, opts *RequestOptions) ([]byte, error) {
	var qb FunctionDownloadFolderQuery
	if q != nil {
		qb = *q
	}
	qb.Path = path
	return g.c.DownloadFolder(ctx, g.id, qb, opts)
}

// UploadFolder Unpacks the request's tar archive (gzip-compressed or not, told by its first bytes) into a folder, made with its parents, by tar in the function as the bytes arrive, of any size, nothing of it kept on disk but what tar writes; returns once tar has ended, or 400 `invalid_archive` with what tar said. A paused function is woken first.
func (g *FunctionMachineFiles) UploadFolder(ctx context.Context, path string, data []byte, q *FunctionUploadFolderQuery, opts *RequestOptions) (*FolderUnpacked, error) {
	var qb FunctionUploadFolderQuery
	if q != nil {
		qb = *q
	}
	qb.Path = path
	return g.c.UploadFolder(ctx, g.id, data, qb, opts)
}

// BeginFolderUpload Begins a folder's upload in parts: tar starts in the function, unpacking into the folder each part as it arrives. Send the parts in order by offset (writeFolderUpload), then commitFolderUpload; an upload no call names for 10 minutes is ended. A paused function is woken first.
func (g *FunctionMachineFiles) BeginFolderUpload(ctx context.Context, path string, in *FolderUploadBegin, opts *RequestOptions) (*FolderUpload, error) {
	var b FolderUploadBegin
	if in != nil {
		b = *in
	}
	b.Path = path
	return g.c.BeginFolderUpload(ctx, g.id, b, opts)
}

// WriteFolderUpload Sends the request's bytes, a part of the archive at its offset, into tar's input as they arrive, of any size, and returns the bytes received in all once tar took them. A part past them is refused 409 `upload_incomplete`, naming them: send the parts in order.
func (g *FunctionMachineFiles) WriteFolderUpload(ctx context.Context, upload string, data []byte, q *FunctionWriteFolderUploadQuery, opts *RequestOptions) (*FolderUploadReceived, error) {
	var qb FunctionWriteFolderUploadQuery
	if q != nil {
		qb = *q
	}
	return g.c.WriteFolderUpload(ctx, g.id, upload, data, qb, opts)
}

// CommitFolderUpload Ends a folder upload's input and returns once tar has ended, as an exec returns once its command has: the folder, or 400 `invalid_archive` with what tar said. A front that restarts meanwhile returns 503 `run_goes_on`; sent again, it returns how tar ended. An upload no call has named for 10 minutes since its last part or commit is ended.
func (g *FunctionMachineFiles) CommitFolderUpload(ctx context.Context, upload string, opts *RequestOptions) (*FolderUnpacked, error) {
	return g.c.CommitFolderUpload(ctx, g.id, upload, opts)
}

// AbortFolderUpload Stops a folder upload's tar; what it unpacked so far stays.
func (g *FunctionMachineFiles) AbortFolderUpload(ctx context.Context, upload string, opts *RequestOptions) (*FolderUploadAborted, error) {
	return g.c.AbortFolderUpload(ctx, g.id, upload, opts)
}

// Mkdir Makes a directory, and its parents unless parents is false. One there already is success, created false.
func (g *FunctionMachineFiles) Mkdir(ctx context.Context, path string, in *FileMkdir, opts *RequestOptions) (*FileMade, error) {
	var b FileMkdir
	if in != nil {
		b = *in
	}
	b.Path = path
	return g.c.Mkdir(ctx, g.id, b, opts)
}

// Rename Moves a file, a link or a directory; refused 409 when something is at its new path, unless overwrite. With sha256 or size, a file written in parts is put in place once whole: its writes ended, then only a file of that size with every byte written and whose bytes hash to it moves; refused 409 `upload_incomplete` or `checksum_mismatch`, nothing moved. With sha256, it is safe to send again: once moved, it returns the same answer while `from` is gone and `to` holds those bytes.
func (g *FunctionMachineFiles) Rename(ctx context.Context, in *FileRename, opts *RequestOptions) (*FileRenamed, error) {
	var b FileRename
	if in != nil {
		b = *in
	}
	return g.c.Rename(ctx, g.id, b, opts)
}

// Link Makes an expiring address for one file that anyone may open with no API key, from a browser, curl or another service: GET downloads it (Range works, so videos play and downloads resume; archive: true downloads a folder as .tar.gz), PUT with the raw body uploads it (up to maxBytes, written whole; Content-Length required). The link acts as the key that made it: an upload link needs write, and the link ends with its key, with revokeLinks or with its function. A paused function is woken for it unless wake is false.
func (g *FunctionMachineFiles) Link(ctx context.Context, path string, in *FileLinkCreate, opts *RequestOptions) (*FileLink, error) {
	var b FileLinkCreate
	if in != nil {
		b = *in
	}
	b.Path = path
	return g.c.Link(ctx, g.id, b, opts)
}

// RevokeLinks Ends every file link made for a function so far; links made after work.
func (g *FunctionMachineFiles) RevokeLinks(ctx context.Context, opts *RequestOptions) (*FileLinksRevoked, error) {
	return g.c.RevokeLinks(ctx, g.id, opts)
}

